export interface Week { id: number; level: "beginner" | "intermediate" | "advanced"; name: string; range: string; blurb: string; }
export interface DayContent { title: string; vocab: string[]; speakTargets: string[]; speaking: string; tip: string; }
export interface SoundGroup { category: string; note: string; targets: string[]; level: "beginner" | "intermediate" | "advanced"; }
export interface Scenario { id: string; label: string; opener: string; }
export interface Level { id: "beginner" | "intermediate" | "advanced"; label: string; range: [number, number]; color: "gold" | "coral" | "cyan"; }

export const LEVELS: Level[] = [
  { id: "beginner", label: "Beginner", range: [1, 31], color: "gold" },
  { id: "intermediate", label: "Intermediate", range: [32, 46], color: "coral" },
  { id: "advanced", label: "Advanced", range: [47, 69], color: "cyan" },
];

export function levelForDay(day: number): Level {
  return LEVELS.find((l) => day >= l.range[0] && day <= l.range[1]) ?? LEVELS[0];
}

