export const TRICKY_SOUNDS: SoundGroup[] = [
  { level: "beginner", category: "V vs W", note: "Telugu often blends these into one sound — English keeps the lips completely different: V bites the lip, W rounds it.", targets: ["I saw a wolf near the village", "We watched the waves in the evening"] },
  { level: "beginner", category: "TH sounds", note: "Put your tongue between your teeth. Don't swap 'th' for 'd' or 't'.", targets: ["I think this is the third time", "That thing is thin and light"] },
  { level: "beginner", category: "Word Stress", note: "The same word changes meaning depending on which part you stress.", targets: ["I need to record this conversation", "This is a broken record"] },
  { level: "beginner", category: "Silent Letters", note: "These letters are written but never spoken out loud.", targets: ["I live on a small island", "She cut the bread with a sharp knife"] },
  { level: "intermediate", category: "Consonant Clusters", note: "Telugu tends to insert a small vowel between consonants that English runs together with no gap at all.", targets: ["She asked for the exact text", "The twelfths of the contract were split evenly"] },
  { level: "intermediate", category: "Linking Sounds", note: "English joins the end of one word to the start of the next — 'an apple' sounds like one word, not two.", targets: ["I want an apple and an orange", "Turn it off and on again"] },
  { level: "intermediate", category: "R Sounds", note: "English R doesn't roll or tap the way Telugu's does — the tongue curls back without touching the roof of the mouth.", targets: ["The library is around the corner", "Robert really rarely arrives early"] },
  { level: "intermediate", category: "Vowel Length", note: "Short and long vowels change the whole word — 'ship' and 'sheep' aren't the same length by accident.", targets: ["The ship left the port at six", "We saw sheep near the hill"] },
  { level: "advanced", category: "Weak Forms & Schwa", note: "Small function words ('to', 'of', 'and') collapse to a lazy 'uh' sound in fast natural speech — saying them fully sounds robotic, not clearer.", targets: ["I'm going to the store for a bit", "A cup of coffee and a slice of toast"] },
  { level: "advanced", category: "Sentence Stress & Rhythm", note: "English stresses content words (nouns, verbs) and rushes through function words — that contrast is the actual rhythm of the language.", targets: ["I never SAID she STOLE the MONEY", "She's the ONE who CALLED me YESTERDAY"] },
  { level: "advanced", category: "Intonation Patterns", note: "Rising pitch signals a question or uncertainty; falling pitch signals a statement or certainty — using the wrong one changes what you sound like you mean.", targets: ["You're coming to the party? (rising — real question)", "You're coming to the party. (falling — assumption stated as fact)"] },
  { level: "advanced", category: "Homograph Stress Shifts", note: "Some words change meaning AND pronunciation depending on stress — same spelling, different word entirely.", targets: ["I need to present the present to her", "Please don't object to this object on my desk"] },
];

